//#region node_modules/three/examples/jsm/shaders/VignetteShader.js
/**
* @module VignetteShader
* @three_import import { VignetteShader } from 'three/addons/shaders/VignetteShader.js';
*/
/**
* Based on [PaintEffect postprocess from ro.me](https://github.com/dataarts/3-dreams-of-black/blob/master/deploy/js/effects/PaintEffect.js).
*
* @constant
* @type {ShaderMaterial~Shader}
*/
var VignetteShader = {
	name: "VignetteShader",
	uniforms: {
		"tDiffuse": { value: null },
		"offset": { value: 1 },
		"darkness": { value: 1 }
	},
	vertexShader: `

		varying vec2 vUv;

		void main() {

			vUv = uv;
			gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );

		}`,
	fragmentShader: `

		uniform float offset;
		uniform float darkness;

		uniform sampler2D tDiffuse;

		varying vec2 vUv;

		void main() {

			// Eskil's vignette

			vec4 texel = texture2D( tDiffuse, vUv );
			vec2 uv = ( vUv - vec2( 0.5 ) ) * vec2( offset );
			gl_FragColor = vec4( mix( texel.rgb, vec3( 1.0 - darkness ), dot( uv, uv ) ), texel.a );

		}`
};
//#endregion
export { VignetteShader };
